{"reasoning": "At each turn, I compute the expected value (mean) of a random draw from each nonempty bag and choose the bag with the highest expected value. In case of a tie in expected value, I pick the bag whose maximum coin is larger, aiming to secure the biggest possible coin. This strategy is simple, efficient, and adapts dynamically to the observed remaining coins.", "code": "from pydantic import BaseModel
from typing import List, Optional, Dict, Any
from enum import Enum
from abc import abstractmethod

from system.message import Info
from system.message import BaseMessageDataType
from model.strategy_type import StrategyType
from model.base import BaseStrategy

class LargerTargetCustomStrategy:
    def __init__(self, model: BaseStrategy):
        self._model = model
        self.name = self._model.name
        self.history = self._model.history
        self.strategy_type = StrategyType.Custom

    def update_model_field(self, field_name: str, value: Any):
        if hasattr(self._model, field_name):
            setattr(self._model, field_name, value)

    def receive_message(self, message: Info) -> Info:  
        data = message.message[0].data
        random_bag: List[List[int]] = data['random_bag']
        empty_bag: List[int] = data['empty_bag']

        empty_set = set(empty_bag)
        chosen_bag = None
        best_expected = -float('inf')

        for i, bag in enumerate(random_bag):
            if i in empty_set or not bag:
                continue
            expected_val = sum(bag) / len(bag)
            if expected_val > best_expected:
                best_expected = expected_val
                chosen_bag = i
            elif expected_val == best_expected:
                # tie-breaker: pick the bag with larger maximum coin
                if max(bag) > max(random_bag[chosen_bag]):
                    chosen_bag = i

        return Info(
            sender=self.__class__.__name__,
            receiver=message.sender,
            difficulty=message.difficulty,
            message=[BaseMessageDataType(data=chosen_bag, type='custom')]
        )"}
